sys_script_include.script:
var AgencyInvoice_auxiliary_functions = Class.create();
AgencyInvoice_auxiliary_functions.prototype = {
    initialize: function() {
    },
	pfdCategoryFormatter: function(array) {
		var res = '';
		for(var i = 0; i<array.length; i++) {
			res += '<p><strong>' + array[i].Modelname + '</strong></p>';
			res += '<p>&nbsp;&nbsp;&nbsp; <strong> Stückzahl: </strong>' + array[i].Stueckzahl;
			res += ', <strong> Kosten: </strong>' + array[i].Kosten;
			res += ', <strong>Mwst: </strong>' + array[i].Mwst + '</p>';
		}
		return res;
	},

	inventarHashcreation : function(array) {
		var res = '';
		for(var i = 0; i<array.length; i++) {
			res += array[i].Modelname + ', ';
			res += array[i].Stueckzahl + ', ';
			res += array[i].Kosten + ', ';
			res += array[i].Mwst + ', ';
		}
		gs.addInfoMessage(res);
		return res;
	},
    type: 'AgencyInvoice_auxiliary_functions'
};
